{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "High-Dose Versus Low-Dose Venous Thromboprophylaxis In Hospitalized Patients With Covid-19: A Systematic Review And Meta-Analysis",
      "reason": "The title explicitly identifies the report as a systematic review (and meta-analysis)."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "High-Dose Versus Low-Dose Venous Thromboprophylaxis In Hospitalized Patients With Covid-19",
      "reason": "The title conveys the population (hospitalized COVID-19 patients) and the intervention/exposure comparison (high-dose vs low-dose venous thromboprophylaxis)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "A Systematic Review And Meta-Analysis",
      "reason": "The title provides supplementary information on the analysis method (meta-analysis)."
    }
  ],
  "confidence": 95
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The combination of systemic activation of coagulation, extensive pulmonary endotheliopathy and thromboinflammatory process caused by SARS-CoV2 results in an increased risk of thrombotic complications... Available data suggested that, despite pharmacologic thromboprophylaxis, there is a substantial residual risk of VTE and a non-negligible risk of bleeding events [3, 5]. In addition, it remains unclear whether prophylactic or higher doses of anticoagulants may reduce in-hospital mortality in COVID-19 patients [6, 7].",
      "reason": "The Introduction describes current knowledge (VTE risk in COVID-19, observational study findings) and explicitly identifies uncertainties (unclear whether higher anticoagulant doses reduce mortality; conflicting RCT findings noted in text_4)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "These observations left clinicians uncertain about the need for higher doses of thromboprophylaxis and resulted in heterogeneous indications from different guidance documents, in particular for critically ill patients.",
      "reason": "The need for the review is explained by clinical uncertainty and inconsistent guidance, and the objective of the systematic review is stated (text_4: 'The objective of this systematic review and meta-analysis was to evaluate the pooled efficacy and safety of high-dose versus low-dose thromboprophylaxis...')."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No similar existing systematic reviews are mentioned or cited anywhere in the retrieved evidence, so no explanation of need relative to prior reviews is required."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although the disease mechanism (coagulation activation, endotheliopathy) is described, the proposed mechanism of action of the intervention itself (heparin/anticoagulant thromboprophylaxis) is not described in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of a relatively simple pharmacological dose-comparison intervention (high- vs low-dose anticoagulation) in a single delivery context; no complex multi-component intervention or logic model requirement applies."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The objective of this systematic-review and meta-analysis was to compare the efficacy and safety of high-dose versus low-dose thromboprophylaxis in hospitalized patients with COVID-19.",
      "reason": "An explicit objective statement is provided in the abstract, and reiterated in the text: 'The objective of this systematic review and meta-analysis was to evaluate the pooled efficacy and safety of high-dose versus low-dose thromboprophylaxis for VTE in hospitalized patients with COVID-19' (text_4)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The objective of this systematic-review and meta-analysis was to compare the efficacy and safety of high-dose versus low-dose thromboprophylaxis in hospitalized patients with COVID-19. ... The primary efficacy outcome was the occurrence of VTE and the primary safety outcome was major bleeding.",
      "reason": "The planned comparison is stated in PICO form: population (hospitalized patients with COVID-19), intervention (high-dose thromboprophylaxis), comparator (low-dose thromboprophylaxis), and outcomes (VTE, major bleeding)."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "RCTs including hospitalized patients with objectively diagnosed SARS-CoV2 infection and comparing high-dose anticoagulation (experimental group) with low-dose anticoagulation (control group) were eligible. Studies with a non-randomised design or published in languages other than English were excluded.",
      "reason": "Eligibility is well specified for design (RCTs only, non-randomised designs excluded), population (hospitalized adult patients with objectively diagnosed SARS-CoV2 infection), intervention (high-dose anticoagulation) and comparator (low-dose anticoagulation), with setting (hospitalized) implied. However, no follow-up requirements (and no outcome-based eligibility criteria) are stated as part of the inclusion/exclusion criteria, so the element is only partially fulfilled."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "Studies with a non-randomised design or published in languages other than English were excluded.",
      "reason": "A language restriction (English only) is explicitly stated. The search window (January 2020 to October 2021) implicitly limits dissemination dates but is not framed as an eligibility criterion, and no publication/report status criterion (e.g., published vs. preprint, peer-reviewed status) is specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_9",
      "quote": "Full-text articles excluded, with reasons (n = 1 – data reported in a previous RCTs)",
      "reason": "Visible in the PRISMA flow diagram image (figure_5, attached to chunk text_9): the only full-text exclusion was because 'data reported in a previous RCTs' (duplicate reporting), not because outcomes were unmeasured or unreported. The text (text_6) confirms all nine included studies reported major bleeding and all-cause mortality, so no outcome-based exclusions occurred and the distinction is not applicable."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Sensitivity analyses were planned to compare the efficacy and safety of intermediate or therapeutic dose versus low-dose thromboprophylaxis, and of high-dose versus lowdose thromboprophylaxis in critically ill and non-critically ill COVID-19 patients. Critically ill patients included those admitted to ICU, patients requiring invasive mechanical ventilation, and patients with severe COVID-19 as defined by the study authors.",
      "reason": "Synthesis groups are explicitly specified and defined: experimental (high-dose, i.e., intermediate or therapeutic dose, per text_4) versus control (low-dose), with subgroup/sensitivity analyses by dose category (intermediate vs therapeutic), illness severity (critically vs non-critically ill, with explicit definitions and a >75% patient threshold rule), intended-dose receipt, and symptomatic VTE. These groups directly link to the stated review objective of evaluating high-dose versus low-dose thromboprophylaxis (text_4)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Notable eligibility restrictions are imposed (RCT-only design, English-language-only publication), but no rationale or justification for these restrictions is provided anywhere in the retrieved evidence."
    }
  ],
  "confidence": 85
}

