      "element_id": "prisma_2020_10a_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not indicate that only a subset of compatible results was collected within outcome domains, so the conditional requirement to describe a result-selection process is not triggered by the available evidence."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to outcome-domain inclusion, definitions, or importance (e.g., protocol amendments) are reported anywhere in the retrieved text, so there is nothing to report with rationale."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to processes for selecting results within outcome domains are reported in the retrieved evidence."
    },
